type Handler = fn(&mut Vm, u8) -> Result<(), Trap>;

fn dispatch(vm: &mut Vm, table: &HashMap<u8, Handler>, op: u8, arg: u8) -> Result<(), Trap> {
    let handler = table.get(&op).ok_or(Trap::UnknownOpcode(op))?;
    handler(vm, arg)
}
