type Op = fn(&mut Chip8, u16);
static TABLE: [Op; 0x10] = [op_err, op_jp, op_call, /* ... */ op_draw, op_err];

fn cycle(&mut self, word: u16) {
    (TABLE[((word & 0xF000) >> 12) as usize])(self, word);
}

trait Handler { fn handle(&self, req: &Request) -> Response; }

fn dispatch(table: &HashMap<String, Box<dyn Handler>>, key: &str, req: &Request)
    -> Option<Response> {
    table.get(key).map(|h| h.handle(req))
}
